import numpy as np
def run():
    def S_theta(thM, thC, thI):
        sM, sC, sI = np.sin(np.radians([thM, thC, thI]))
        return 1/sM**2 + 1/sC**2 + 1/sI**2 + 1/(sM*sC) + 1/(sM*sI) + 1/(sC*sI)
    def Q(thM, thC, thI):
        return np.sin(np.radians(thC))*np.sin(np.radians(thI))*np.sqrt(S_theta(thM, thC, thI))
    def f(v_deg, alpha_deg):
        a = np.radians(alpha_deg); v = np.radians(v_deg)
        ca, sa2 = np.cos(a), np.sin(a/2); w = np.cos(v)
        return 1 - ca/2 + w*(0.5-ca) + (w-ca)*sa2*np.cos(v/2)/ca + (w-ca)**2/(4*ca**2)
    alpha0, thM0 = 32.07, 57.93
    maxerr = 0.0
    for v in [-25, -15, -5, 0, 5, 10, 15, 20]:
        thC = (alpha0+v)/2; thI = (alpha0-v)/2
        num = Q(thM0, thC, thI)**2
        err = abs(num - f(v, alpha0))/num
        maxerr = max(maxerr, err)
    f0 = f(0, alpha0); fma = f(-alpha0, alpha0)
    bulge = np.sqrt(f0/fma) - 1
    # 1% 带边界（二分）
    def Qvar(a):
        vs = np.linspace(-a, 2*26.16-a, 4000)
        fs = np.array([f(v, a) for v in vs])
        return np.sqrt(fs.max()/fs.min()) - 1
    lo, hi = 28.5, 34.0
    for _ in range(40):
        mid = (lo+hi)/2
        if Qvar(mid) < 0.01: lo = mid
        else: hi = mid
    upper = lo
    lo2, hi2 = 27.0, 30.0
    for _ in range(40):
        mid = (lo2+hi2)/2
        if Qvar(mid) < 0.01: hi2 = mid
        else: lo2 = mid
    lower = hi2
    return {"values": {"闭式最大误差": f"{maxerr:.2e}", "f(-α)=sin²α": f"{fma:.6f}",
                       "隆起Q(0)/Q(-α)-1": f"{bulge:.4%}", "1%带": f"[{lower:.3f}, {upper:.3f}]"},
            "conclusion": f"闭式恒等（误差<{maxerr:.0e}）；f(−α)=sin²α 精确；α=32.07° 隆起 {bulge:.3%}；1% 守恒带 [{lower:.3f}°, {upper:.3f}°]"}

