import numpy as np
def run():
    def f_vals(vs_deg, alpha_deg):
        a = np.radians(alpha_deg); vs = np.radians(vs_deg)
        ca, sa2 = np.cos(a), np.sin(a/2); w = np.cos(vs)
        return 1 - ca/2 + w*(0.5-ca) + (w-ca)*sa2*np.cos(vs/2)/ca + (w-ca)**2/(4*ca**2)
    best = None
    for a in np.linspace(28, 34, 241):
        vs = np.linspace(-a, 2*26.16-a, 800)
        fs = f_vals(vs, a)
        df = np.gradient(fs, np.radians(vs[1]-vs[0]))
        l2 = np.sqrt(np.mean(df**2))
        if best is None or l2 < best[1]:
            best = (a, l2)
    # 局部 f''(0)=0 临界（对照）
    def fpp0(a):
        a = np.radians(a); ca = np.cos(a); sa2 = np.sin(a/2)
        return -(0.5-ca) - sa2*(1+(1-ca)/4)/ca - (1-ca)/(2*ca**2)
    from scipy.optimize import brentq
    astar = brentq(fpp0, 28, 30)
    return {"values": {"L²最优α": f"{best[0]:.2f}°", "f''(0)=0临界": f"{astar:.3f}°",
                       "圆满再现α⁰": "32.07°", "α⁰距最优": f"{32.07-best[0]:.2f}°"},
            "conclusion": f"全路径平坦最优 α* = {best[0]:.2f}°（f' L² 最小）；圆满再现锁定 32.07° 距最优 {32.07-best[0]:.2f}°——相容但非最优"}

