import numpy as np
def run():
    def S_theta(thM, thC, thI):
        sM, sC, sI = np.sin(np.radians([thM, thC, thI]))
        return 1/sM**2 + 1/sC**2 + 1/sI**2 + 1/(sM*sC) + 1/(sM*sI) + 1/(sC*sI)
    def Q(thM, thC, thI):
        return np.sin(np.radians(thC))*np.sin(np.radians(thI))*np.sqrt(S_theta(thM, thC, thI))
    thM0, alpha0 = 57.93, 32.07
    tcs = np.linspace(0.5, 25.5, 400)
    qs = np.array([Q(thM0, tc, alpha0-tc) for tc in tcs])
    imax = np.argmax(qs)
    # lnQ² 曲率（沿 θ_C 二阶导，细网格）
    eps = 1e-3
    curv = []
    for tc in np.linspace(1.0, 25.0, 200):
        l = lambda t: np.log(Q(thM0, t, alpha0-t)**2)
        curv.append((l(tc+eps) - 2*l(tc) + l(tc-eps))/eps**2)
    signs = np.sign(curv)
    nflip = int(np.sum(signs[1:] != signs[:-1]))
    return {"values": {"峰位置θ_C": f"{tcs[imax]:.2f}°", "α/2": f"{alpha0/2:.2f}°",
                       "Q变化": f"{(qs.max()/qs.min()-1):.3%}", "lnQ²曲率变号": f"{nflip}"},
            "conclusion": f"Q 单峰：峰在 θ_C = {tcs[imax]:.2f}° ≈ α/2 = {alpha0/2:.2f}°；Q 全程变化 {(qs.max()/qs.min()-1):.3%}；lnQ² 曲率变号 {nflip} 次（单峰结构）"}
